r"""Chapter 2: optical heating, activation, finite PFC phase inventory.

Worker-owned content only. Equations and diagrams are rendered by coursekit.
"""
from coursekit import P, H, E, T, cite, defense, note
from symbol_tables import glossary

b = []
b.append(H("2. Optical heating and finite PFC inventory", "2. 光学加热与有限 PFC 物质量", r'system'))
b.append(P(
    "Calculate the pressure history of one laser-heated PFC inclusion. Chapter 1 derived the response to prescribed internal pressure. This chapter supplies absorption, heating, activation, mass and energy balances. The emitted jet usually consists mainly of carrier liquid. Use PFC density for core inventory and carrier density for inertia. Lower activation threshold leaves emitted momentum and transfer repeatability unresolved.",
    "本章计算单个激光加热 PFC 夹杂的压力历程。第一章推导给定内压下的响应，本章补充吸收、加热、激活、质量和能量平衡。喷出射流通常主要由载液组成。核心物质量采用 PFC 密度，惯性采用载液密度。较低激活阈值仍不能确定喷出动量与转印重复性。"))
b.append(P(
    "<strong>System and conventions.</strong> Place an initially liquid spherical PFC core in aqueous carrier. Initial temperature is $T_0$ (K); carrier pressure is $p_c$ (Pa). Beam depth $z$ (m) increases along propagation. Transverse radius $r$ (m) measures distance from its axis. Time $t=0$ (s) precedes the pulse. Prescribe entering intensity and initial temperature field. Symmetry gives zero center heat flux. Specify an outer reservoir or resolve the surrounding carrier. Enforce contact flux continuity and the chosen contact law. Thermodynamic pressures are absolute. Unit normal $\\boldsymbol n$ points from liquid into vapor. Positive flux denotes evaporation. Inside a bubble, this normal opposes outward radial unit vector $\\boldsymbol e_r$.",
    "<strong>体系与约定。</strong> 初始液态球形 PFC 核位于水相载液中。初温为 $T_0$（K），载液压力为 $p_c$（Pa）。光束深度 $z$（m）沿传播方向增加。横向半径 $r$（m）为距光轴距离。$t=0$（s）位于脉冲之前。给定入射强度与初始温度场。中心对称性给出零热通量。外边界采用指定热库，或解析周围载液。材料接触处满足通量连续及所选接触规律。热力学压力均为绝对压力。单位法向 $\\boldsymbol n$ 从液体指向蒸气，正通量表示蒸发。气泡内部的该法向与向外径向单位矢量 $\\boldsymbol e_r$ 相反。"))
b.append(P(
    "<strong>Approximation sequence.</strong> The optical model neglects scattering and nonlinear absorption. Pre-phase heating omits pressure work and viscous heat in nearly incompressible phases. Nucleation assumes local isothermality and a nucleus much smaller than the liquid core. Uniform-bubble closure assumes common temperature and a dilute ideal mixture. Each approximation has its own validity range. The micron-sized teaching core does not represent a nanodroplet.",
    "<strong>近似顺序。</strong> 光学模型忽略散射与非线性吸收。相变前的近不可压缩相加热忽略压力功和黏性热。成核假设局部等温且汽核远小于液核。均匀气泡闭合假设共同温度及稀薄理想混合物。每项近似均有独立适用范围。微米教学核心不代表纳米液滴。"))
b.append(glossary(2))
b.append(P(
    "Match a PFC-free aqueous control to the PFC case. Keep outer geometry, absorber location, absorbed energy and initial state comparable. Also match outlet and target load path. Simultaneous absorber or spot-size changes confound the material comparison. Measure activation, emitted mass and speed, useful impulse, intact yield and reset. Retained vapor can ease activation while cushioning later collapse.",
    "将不含 PFC 的水相对照与 PFC 情形匹配。保持外部几何、吸收体位置、吸收能量和初态可比，并匹配出口及目标传力路径。同时改变吸收体或光斑会混淆材料比较。测量激活、喷出质量与速率、有用冲量、完整转印率及复位。残留蒸气可促进激活，同时缓冲后续塌缩。"))

b.append(H("2.1 Incident and absorbed energy", "2.1 入射与吸收能量", r'optics'))
b.append(P(
    "<strong>Step 1 — Define Gaussian fluence.</strong> Fluence integrates irradiance over time. Specify its transverse profile. Define beam radius at the $e^{-2}$ level whenever quoting spot size.",
    "<strong>步骤 1——定义高斯能量面密度。</strong> 能量面密度为辐照度的时间积分。先规定横向分布。标注光斑尺寸时，采用 $e^{-2}$ 水平定义光束半径。"))
b.append(E(r'C2-E01', r'F(r)=F_0\exp(-2r^2/w^2)',
    r'$F(r)$ is incident fluence at radial coordinate $r\ge0$ (J m⁻²); $F_0>0$ is on-axis fluence (J m⁻²); $w>0$ is the transverse $e^{-2}$ beam radius (m); $\exp$ is the natural exponential.',
    r'$F(r)$ 为径向坐标 $r\ge0$ 处的入射能量密度（J m⁻²）；$F_0>0$ 为轴上能量密度（J m⁻²）；$w>0$ 为横向 $e^{-2}$ 光束半径（m）；$\exp$ 为自然指数函数。',
    r'Prescribed optical profile', {r'type':r'laser',r'labels':[r'r: transverse radius',r'w: e⁻² beam radius',r'F(r), F₀: fluence'], r'notes':[r'Beam axis at r = 0',r'Gaussian profile across the illuminated plane']},
    r'Fluence varies across the beam; the quoted radius fixes its definition.', r'能量密度沿光束横向变化；所给半径明确其定义。'))
b.append(P(
    "<strong>Step 2 — Integrate the beam plane.</strong> The annular area is $2\\pi r\\,dr$. Substitute $x=2r^2/w^2$, giving $dx=4r\\,dr/w^2$. Limits remain zero and infinity. The integral converges. The exponential decays to zero at infinity.",
    "<strong>步骤 2——积分光束平面。</strong> 环形面积为 $2\\pi r\\,dr$。令 $x=2r^2/w^2$，则 $dx=4r\\,dr/w^2$。积分限仍为零与无穷远。积分收敛，指数函数在无穷远趋零。"))
b.append(E(r'C2-E02', r'\begin{aligned}E_L&=2\pi F_0\int_0^\infty r e^{-2r^2/w^2}\,dr\\&=\frac{\pi w^2F_0}{2}\int_0^\infty e^{-x}\,dx\\&=\frac{\pi w^2F_0}{2}[-e^{-x}]_0^\infty=\frac{\pi w^2F_0}{2}.\end{aligned}',
    r'$E_L$ is total incident pulse energy (J); $F_0$ is on-axis fluence (J m⁻²); $w>0$ and $r\ge0$ are beam radius and transverse distance (m); $x=2r^2/w^2$ is a dimensionless substitution variable; $\pi$ is the circular constant; $e^x$ is the exponential; $\int$ and brackets denote integration and endpoint evaluation.',
    r'$E_L$ 为总入射脉冲能量（J）；$F_0$ 为轴上能量密度（J m⁻²）；$w>0$ 和 $r\ge0$ 分别为光束半径与横向距离（m）；$x=2r^2/w^2$ 为无量纲换元变量；$\pi$ 为圆周率；$e^x$ 为指数函数；$\int$ 与方括号表示积分及端点求值。',
    r'Exact integral of the prescribed profile', {r'type':r'laser',r'labels':[r'E_L: sum over annuli',r'F₀: central fluence',r'r, w: transverse geometry',r'x = 2r²/w²',r'π: circular annuli'], r'notes':[r'Annulus area = 2πr dr',r'Integral of e⁻ˣ from 0 to infinity = 1']},
    r'The Gaussian energy follows from summing annular contributions.', r'高斯光束能量来自环带贡献之和。'))
b.append(P(
    "<strong>Step 3 — Calculate intercepted energy.</strong> End the same integral at centered aperture radius $b_a$ (m). Divide by total beam energy. Off-axis or irregular absorbers require their actual area integral.",
    "<strong>步骤 3——计算截获能量。</strong> 将同一积分上限取为居中孔径半径 $b_a$（m），再除以总光束能量。偏轴或不规则吸收体须按实际区域积分。"))
b.append(E(r'C2-E03', r'f_{\mathrm{geo}}=\frac{\int_0^{b_a}F(r)2\pi r\,dr}{E_L}=1-\exp(-2b_a^2/w^2),\qquad 0\le f_{\mathrm{geo}}\le1',
    r'$f_{\mathrm{geo}}$ is intercepted energy fraction (dimensionless), with label geo meaning geometry; $b_a\ge0$ is centered absorber-aperture radius (m); $F(r)$ is Gaussian fluence (J m⁻²); $r$ is transverse integration distance (m); $E_L>0$ is total pulse energy (J); $w>0$ is beam radius (m); $\pi$ is the circular constant; $\exp$ and $\int$ denote exponential and integration.',
    r'$f_{\mathrm{geo}}$ 为截获能量比例（无量纲），geo 下标表示几何；$b_a\ge0$ 为同轴吸收体窗口半径（m）；$F(r)$ 为高斯能量密度（J m⁻²）；$r$ 为横向积分距离（m）；$E_L>0$ 为总脉冲能量（J）；$w>0$ 为光束半径（m）；$\pi$ 为圆周率；$\exp$ 和 $\int$ 表示指数函数与积分。',
    r'Derived interception fraction', {r'type':r'laser',r'labels':[r'b_a: absorber aperture edge',r'w: beam radius',r'r, F(r): intercepted annuli',r'E_L: full incident energy',r'f_geo: intercepted fraction',r'π: annulus geometry'], r'notes':[r'b_a → 0 gives no interception',r'b_a ≫ w captures nearly all beam energy']},
    r'The aperture removes the outer annuli from the useful incident energy.', r'窗口使外侧环带不再计入有用入射能量。'))
b.append(P(
    "<strong>Step 4 — Include pulse duration.</strong> Normalize the temporal pulse shape to unit integral. A rectangular pulse has height equal to reciprocal duration. Shorter duration raises irradiance at fixed fluence. Incident energy stays fixed.",
    "<strong>步骤 4——加入脉冲时长。</strong> 将时间脉冲形状归一化为单位积分。矩形脉冲高度等于时长的倒数。能量面密度固定时，缩短时长会提高辐照度，入射能量保持不变。"))
b.append(E(r'C2-E04', r'\int_{-\infty}^{\infty} f(t)\,dt=1,\qquad I(r,t)=F(r)f(t),\qquad I_{\mathrm{peak}}=F_0/\tau_L\quad\text{(rectangular pulse)}',
    r'$f(t)\ge0$ is normalized pulse shape (s⁻¹); $t$ is time (s); $I(r,t)$ is irradiance (W m⁻²); $F(r)$ and $F_0$ are local and central fluence (J m⁻²); $r$ is transverse distance (m); $I_{\mathrm{peak}}$ is central peak irradiance (W m⁻²); $\tau_L>0$ is rectangular laser-pulse duration (s), with L naming laser; $\int$ is time integration.',
    r'$f(t)\ge0$ 为归一化脉冲形状（s⁻¹）；$t$ 为时间（s）；$I(r,t)$ 为辐照度（W m⁻²）；$F(r)$ 和 $F_0$ 为局部与中心能量密度（J m⁻²）；$r$ 为横向距离（m）；$I_{\mathrm{peak}}$ 为中心峰值辐照度（W m⁻²）；$\tau_L>0$ 为矩形激光脉冲时长（s），L 表示激光；$\int$ 为时间积分。',
    r'Temporal profile definition', {r'type':r'laser',r'labels':[r't: pulse time',r'τ_L: pulse width',r'f(t): normalized profile',r'I(r,t), I_peak: irradiance',r'r: transverse position',r'F(r), F₀: integrated fluence'], r'notes':[r'Area under f(t) is 1',r'Peak irradiance and pulse energy are different observables']},
    r'A pulse waveform specifies when the energy is deposited.', r'脉冲波形规定能量何时沉积。'))
b.append(P(
    "<strong>Step 5 — Solve absorption transport.</strong> Irradiance loss across a slab equals deposited heat per volume × thickness. Assume constant positive absorption coefficient. Separate and integrate from entry face to depth, then exponentiate. Optical transit is instantaneous relative to thermal evolution.",
    "<strong>步骤 5——求解吸收输运。</strong> 薄层辐照度损失等于单位体积沉积热量乘以厚度。假设吸收系数为正常数。分离变量，从入射面积分至指定深度，再取指数。相对于热演化，将光传播视为瞬时过程。"))
b.append(E(r'C2-E05', r'\begin{aligned}\partial_z I&=-\mu_a I,& Q_{\mathrm{abs}}&=\mu_a I,\\ \int_{I_{\mathrm{in}}}^{I(z)}\frac{dI^{\prime}}{I^{\prime}}&=-\int_0^z\mu_a\,dz^{\prime},&I(z)&=I_{\mathrm{in}}e^{-\mu_a z}.\end{aligned}',
    r'$z\ge0$ is absorber depth (m); $\partial_z$ denotes differentiation in depth; $I(z)>0$ and $I_{\mathrm{in}}>0$ are local and entry irradiance (W m⁻²), with in labeling entry; $\mu_a>0$ is constant absorption coefficient (m⁻¹), with a labeling absorption; $Q_{\mathrm{abs}}$ is volumetric optical heat deposition (W m⁻³); $I^{\prime}$ and $z^{\prime}$ are integration dummy variables with the same units as $I$ and $z$; $\int$ denotes integration; $e^x$ denotes the exponential. Zero input gives identically zero deposition without dividing by irradiance.',
    r'$z\ge0$ 为吸收体深度（m）；$\partial_z$ 表示对深度求导；$I(z)>0$ 和 $I_{\mathrm{in}}>0$ 为局部与入口辐照度（W m⁻²），in 表示入口；$\mu_a>0$ 为常数吸收系数（m⁻¹），a 表示吸收；$Q_{\mathrm{abs}}$ 为光学体积生热率（W m⁻³）；$I^{\prime}$ 与 $z^{\prime}$ 为积分哑变量，单位分别与 $I$、$z$ 相同；$\int$ 表示积分；$e^x$ 表示指数函数。零输入时沉积恒为零，无须除以辐照度。',
    r'Beer–Lambert constitutive model and solution', {r'type':r'laser',r'labels':[r'z: propagation depth',r'I_in: entry face',r'I(z): transmitted beam',r'μ_a: absorption per depth',r'Q_abs: heat inside slab',r'I′, z′: integration variables'], r'notes':[r'Positive z points into absorber',r'Photon power lost from beam becomes thermal source under this model']},
    r'The absorber deposits heat over a finite optical depth.', r'吸收体在有限光学深度内沉积热量。'))
b.append(P(
    "<strong>Step 6 — Integrate deposited heat.</strong> Integrate the volume source over depth to obtain absorbed power/area. Integrate pulse time and intercepted area to obtain energy. Apply the entering fraction from front-face reflection once. The defined effective absorptance already contains that reflection.",
    "<strong>步骤 6——积分沉积热。</strong> 对体积源沿深度积分，得到单位面积吸收功率。再对脉冲时间及截获面积积分，得到能量。前表面反射造成的入射比例计入一次。所定义有效吸收率已包含该反射。"))
b.append(E(r'C2-E06', r'\begin{aligned}\int_0^{h_a}Q_{\mathrm{abs}}\,dz&=I_{\mathrm{in}}(1-e^{-\mu_a h_a}),\\ A_\lambda&=(1-\mathcal R_\lambda)(1-e^{-\mu_a h_a}),\\ E_{\mathrm{abs}}&=f_{\mathrm{geo}}A_\lambda E_L=\int\!\int_{\Omega_a}Q_{\mathrm{abs}}\,dV\,dt.\end{aligned}',
    r'$h_a>0$ is uniform absorber thickness (m); $z$ is depth (m); $Q_{\mathrm{abs}}$ is volumetric heat source (W m⁻³); $I_{\mathrm{in}}$ is irradiance entering the slab (W m⁻²); $\mu_a$ is absorption coefficient (m⁻¹); $\mathcal R_\lambda\in[0,1]$ is front-face reflected energy fraction at wavelength $\lambda$ (m); $A_\lambda$ is effective incident-light absorptance (dimensionless); $f_{\mathrm{geo}}$ is intercepted fraction; $E_L,E_{\mathrm{abs}}$ are incident and absorbed energies (J); $\Omega_a$ is absorbing volume, $dV$ its volume element (m³); $t,dt$ denote time and its element (s); $\int$ is integration; $e^x$ is the exponential.',
    r'$h_a>0$ 为均匀吸收体厚度（m）；$z$ 为深度（m）；$Q_{\mathrm{abs}}$ 为体积热源（W m⁻³）；$I_{\mathrm{in}}$ 为进入薄层的辐照度（W m⁻²）；$\mu_a$ 为吸收系数（m⁻¹）；$\mathcal R_\lambda\in[0,1]$ 为波长 $\lambda$（m）处前表面的反射能量比例；$A_\lambda$ 为相对于入射光的有效吸收率（无量纲）；$f_{\mathrm{geo}}$ 为截获比例；$E_L,E_{\mathrm{abs}}$ 为入射与吸收能量（J）；$\Omega_a$ 为吸收体体积，$dV$ 为其体积元（m³）；$t,dt$ 为时间及其微元（s）；$\int$ 为积分；$e^x$ 为指数函数。',
    r'Derived optical-energy balance', {r'type':r'laser',r'labels':[r'h_a: slab thickness',r'z: depth',r'Ω_a, dV: absorbing volume',r'I_in: light after reflection',r'μ_a, Q_abs: optical heating',r'λ, ℛ_λ, A_λ: wavelength and fractions',r'f_geo, E_L, E_abs: energy accounting',r't: pulse integration'], r'notes':[r'Reflection occurs before entry',r'Integrate the source once; do not add equivalent boundary heating again']},
    r'Interception, reflection, and internal absorption each act once.', r'截获、反射与内部吸收各作用一次。'))
b.append(P(
    "Absorptance approaches zero at zero optical thickness. At large thickness, it approaches the entering fraction. $Q_{\\mathrm{abs}}$ has units W m⁻³; its volume–time integral has units J. Scattering, multiple reflection, saturation and plasma formation require other models. A boundary source can replace an equivalent resolved layer. Including both duplicates the deposited energy.",
    "光学厚度趋零时，吸收率趋零。厚度很大时，吸收率趋于进入比例。$Q_{\\mathrm{abs}}$ 单位为 W m⁻³，其体积—时间积分为 J。散射、多次反射、饱和及等离子体形成需其他模型。等效边界热源可替代解析层，同时加入两者会重复计入能量。"))
b.append(P(
    "Strohm et al. optically activated PbS-loaded PFP at 1064 nm. Wei et al. used gold-containing PFH nanoemulsion. These studies establish formulation-specific optical activation routes. Universal threshold, jet speed and transfer yield remain unestablished. Absorber placement and formulation require experimental inputs. "+cite(r'r6')+r' '+cite(r'r7'),
    "Strohm 等用 1064 nm 激光激活含 PbS 的 PFP。Wei 等采用含金 PFH 纳米乳液。这些研究确立了特定配方的光学激活路径。通用阈值、射流速率及转印率尚未确立。吸收体位置与配方须由实验给定。 "+cite(r'r6')+r' '+cite(r'r7')))

b.append(H("2.2 Heat delivery and event time", "2.2 热输送与事件时间", r'heat'))
b.append(P(
    "<strong>Step 7 — Conserve thermal energy.</strong> Before phase change, conduction and absorption change sensible enthalpy. Assume constant properties in nearly incompressible phases. Omit viscous heating and pressure work. Use near-constant-pressure heat capacity. Moving liquid advects heat; a solid absorber has zero velocity. Conductive flux points down the temperature gradient. Its negative divergence supplies heat influx.",
    "<strong>步骤 7——热能守恒。</strong> 相变前，传导与吸收改变显焓。近不可压缩相采用常物性，忽略黏性热与压力功，使用近恒压热容。运动液体对流输热，固体吸收体速度为零。传导热通量指向温度降低方向，其负散度表示热流入。"))
b.append(E(r'C2-E07', r'\boldsymbol q=-k\nabla T,\qquad \rho c_p\frac{DT}{Dt}=\rho c_p(\partial_tT+\boldsymbol u\cdot\nabla T)=-\nabla\cdot\boldsymbol q+Q_{\mathrm{abs}}=\nabla\cdot(k\nabla T)+Q_{\mathrm{abs}}',
    r'$\boldsymbol q$ is conductive heat flux (W m⁻²); $k>0$ is thermal conductivity (W m⁻¹ K⁻¹); $T$ is temperature (K); $\rho>0$ is phase density (kg m⁻³); $c_p>0$ is constant specific heat capacity (J kg⁻¹ K⁻¹); $t$ is time (s); $\boldsymbol u$ is material velocity (m s⁻¹); $Q_{\mathrm{abs}}$ is optical heating (W m⁻³); $D/Dt$ is the material derivative; $\partial_t$ is the fixed-position time derivative; $\nabla$ and $\nabla\cdot$ are spatial gradient and divergence (m⁻¹); the centered dot here is a vector contraction, not punctuation.',
    r'$\boldsymbol q$ 为传导热通量（W m⁻²）；$k>0$ 为导热系数（W m⁻¹ K⁻¹）；$T$ 为温度（K）；$\rho>0$ 为该相密度（kg m⁻³）；$c_p>0$ 为常数比热容（J kg⁻¹ K⁻¹）；$t$ 为时间（s）；$\boldsymbol u$ 为物质速度（m s⁻¹）；$Q_{\mathrm{abs}}$ 为光生热率（W m⁻³）；$D/Dt$ 为物质导数；$\partial_t$ 为固定位置时间导数；$\nabla$ 与 $\nabla\cdot$ 为空间梯度和散度（m⁻¹）；式中的中心点表示向量缩并，不是标点。',
    r'Reduced heat equation and Fourier constitutive law', {r'type':r'phase',r'labels':[r'T: core temperature field',r'ρ, c_p: stored sensible energy',r'k, q: conduction toward colder material',r'u: parcel advection',r'Q_abs: absorber heating',r't, D/Dt, ∂_t: time changes',r'∇, ∇·: spatial variation'], r'notes':[r'Absorber and PFC can occupy different locations',r'This equation precedes phase change; latent transfer is added at the interface']},
    r'Heating the absorber and heating the PFC are separate parts of the thermal path.', r'加热吸收体与加热 PFC 是热路径中的不同环节。'))
b.append(P(
    "<strong>Step 8 — Close thermal contacts.</strong> Orient the normal from material A into B. Positive normal heat flux travels from A to B. Without surface heat storage, flux is continuous. Nonnegative contact resistance permits a temperature jump. Zero resistance gives temperature continuity. This contact differs from the phase-change interface below.",
    "<strong>步骤 8——闭合热接触。</strong> 法向从材料 A 指向 B，正法向热通量由 A 流向 B。无界面热储存时，通量连续。非负接触热阻允许温度跳跃，零热阻给出温度连续。该接触不同于下文相变界面。"))
b.append(E(r'C2-E08', r'q_n=\boldsymbol q_A\cdot\boldsymbol n_{AB}=\boldsymbol q_B\cdot\boldsymbol n_{AB},\qquad T_A-T_B=\mathcal R_T q_n',
    r'$q_n$ is signed normal heat flux (W m⁻²); $\boldsymbol q_A,\boldsymbol q_B$ are conductive fluxes in materials labeled A and B (W m⁻²); $\boldsymbol n_{AB}$ is unit normal from A into B (dimensionless); $T_A,T_B$ are temperatures at the two contact sides (K); $\mathcal R_T\ge0$ is area-specific thermal contact resistance (m² K W⁻¹); $\cdot$ denotes a vector dot product.',
    r'$q_n$ 为带符号法向热通量（W m⁻²）；$\boldsymbol q_A,\boldsymbol q_B$ 为标记 A、B 的材料内的传导热通量（W m⁻²）；$\boldsymbol n_{AB}$ 为从 A 指向 B 的单位法向（无量纲）；$T_A,T_B$ 为接触面两侧温度（K）；$\mathcal R_T\ge0$ 为单位面积热接触阻力（m² K W⁻¹）；$\cdot$ 表示向量点积。',
    r'Thermal-contact boundary conditions', {r'type':r'phase',r'labels':[r'A: absorber side, T_A, q_A',r'B: PFC side, T_B, q_B',r'n_AB: A → B',r'q_n: continuous normal flux',r'ℛ_T: contact resistance'], r'notes':[r'Hot A gives positive q_n when T_A > T_B',r'No stored heat at the contact in this control']},
    r'Contact resistance delays heat transfer even after the light has been absorbed.', r'即使光已被吸收，接触热阻仍会延迟热传递。'))
b.append(P(
    "<strong>Step 9 — Derive diffusion scales.</strong> Divide the motionless heat equation by volumetric heat capacity. Estimate its time derivative and spatial second derivative over the heating distance. Balance them to obtain diffusion time and penetration length. These are scales rather than sharp thermal fronts. Heating duration may include conduction after the optical pulse.",
    "<strong>步骤 9——推导扩散尺度。</strong> 将静止介质热方程除以体积热容。按加热距离估算时间导数与空间二阶导数。平衡两者，得到扩散时间和渗透长度。它们是尺度估计，并非尖锐热前沿。加热时长可包含光脉冲之后的传导。"))
b.append(E(r'C2-E09', r'\alpha=\frac{k}{\rho c_p},\qquad \frac{\Delta T}{t_{\mathrm{th}}}\sim\alpha\frac{\Delta T}{L_h^2},\qquad t_{\mathrm{th}}\sim\frac{L_h^2}{\alpha},\qquad \delta_T\sim\sqrt{\alpha\tau_h}',
    r'$\alpha>0$ is thermal diffusivity (m² s⁻¹); $k,\rho,c_p$ are phase conductivity (W m⁻¹ K⁻¹), density (kg m⁻³), and specific heat (J kg⁻¹ K⁻¹); $\Delta T\ne0$ is characteristic temperature change (K); $L_h>0$ is heating distance (m); $t_{\mathrm{th}}$ is diffusion time estimate (s); $\tau_h>0$ is available heating duration (s); $\delta_T$ is penetration estimate (m); $\sim$ means order-of-magnitude scaling, not equality.',
    r'$\alpha>0$ 为热扩散率（m² s⁻¹）；$k,\rho,c_p$ 为该相导热系数（W m⁻¹ K⁻¹）、密度（kg m⁻³）及比热容（J kg⁻¹ K⁻¹）；$\Delta T\ne0$ 为特征温度变化（K）；$L_h>0$ 为加热距离（m）；$t_{\mathrm{th}}$ 为扩散时间估计（s）；$\tau_h>0$ 为可用加热时长（s）；$\delta_T$ 为渗透深度估计（m）；$\sim$ 表示量级尺度关系，不表示严格相等。',
    r'Diffusive scaling derived from the heat equation', {r'type':r'timescale',r'labels':[r'L_h: absorber-to-core heating distance',r'δ_T: penetration during τ_h',r'α = k/(ρc_p)',r'ΔT: thermal change',r't_th: diffusion time',r'τ_h: available heating duration'], r'notes':[r'Long distance costs time quadratically',r'Optical pulse duration is not automatically whole-core heating duration']},
    r'Compare heat penetration with the distance to the PFC, not only with beam width.', r'应比较热渗透尺度与到达 PFC 的距离，而不只是光束宽度。'))
b.append(P(
    "<strong>Thermal example.</strong> Prescribe density 1630 kg m⁻³, heat capacity 654 J kg⁻¹ K⁻¹, and conductivity 0.050 W m⁻¹ K⁻¹. The rounded near-293 K heat capacity uses the cited NIST datum. Density and conductivity are teaching inputs. Heating distance is 5 μm; duration is 10 ns.",
    "<strong>热学示例。</strong> 规定密度 1630 kg m⁻³、热容 654 J kg⁻¹ K⁻¹、导热率 0.050 W m⁻¹ K⁻¹。近 293 K 的舍入热容采用所引 NIST 数据。密度与导热率为教学输入。加热距离为 5 μm，时长为 10 ns。"))
b.append(E(r'C2-E10', r'\begin{aligned}\alpha_d&=\frac{0.050}{1630(654)}=4.69034\times10^{-8}\ \mathrm{m^2\,s^{-1}},\\t_{\mathrm{th}}&\sim\frac{(5\times10^{-6})^2}{4.69034\times10^{-8}}=5.33010\times10^{-4}\ \mathrm{s},\\\delta_T&\sim\sqrt{(4.69034\times10^{-8})(10^{-8})}=2.16572\times10^{-8}\ \mathrm{m}.\end{aligned}',
    r'$\alpha_d$ is declared PFC-liquid diffusivity (m² s⁻¹), with d labeling droplet liquid; $t_{\mathrm{th}}$ is diffusion-time estimate (s); $\delta_T$ is penetration estimate (m). The numerator 0.050 is conductivity in W m⁻¹ K⁻¹; 1630 is density in kg m⁻³; 654 is specific heat in J kg⁻¹ K⁻¹; $5\times10^{-6}$ is distance in m; $10^{-8}$ is duration in s. Powers are numerical exponents, and $\sim$ denotes a scale estimate.',
    r'$\alpha_d$ 为所声明 PFC 液体的热扩散率（m² s⁻¹），d 表示液滴液体；$t_{\mathrm{th}}$ 为扩散时间估计（s）；$\delta_T$ 为渗透深度估计（m）。分子 0.050 为导热系数，单位 W m⁻¹ K⁻¹；1630 为密度，单位 kg m⁻³；654 为比热容，单位 J kg⁻¹ K⁻¹；$5\times10^{-6}$ 为距离，单位 m；$10^{-8}$ 为时长，单位 s。幂为数值指数，$\sim$ 表示尺度估计。',
    r'Declared-input thermal calculation', {r'type':r'timescale',r'labels':[r'α_d = 4.69034×10⁻⁸ m²/s',r'L_h = 5 μm',r'τ_h = 10 ns',r't_th ≈ 533 μs',r'δ_T ≈ 21.66 nm',r'k_d = 0.050, ρ_d = 1630, c_p,d = 654 (SI)'], r'notes':[r'Heated shell is much thinner than the core',r'Distributed absorbers or later conduction must justify a uniform-core model']},
    r'A short pulse does not imply uniform temperature in a micron-scale core.', r'短脉冲不意味着微米级核心内温度均匀。'))
b.append(P(
    "Penetration is 0.00433 of the heating distance. Uniform core temperature requires distributed heating or additional diffusion time. At 100 nm, the diffusion estimate falls to 0.213 μs. That still exceeds 10 ns. Hotspots, aggregation and shell contact can dominate local heating. Optical breakdown requires its own optical conditions and observations.",
    "渗透长度为加热距离的 0.00433 倍。核心均温需要分布式加热或额外扩散时间。距离降至 100 nm 时，扩散估计降至 0.213 μs，仍长于 10 ns。热点、团聚和壳层接触可主导局部加热。光学击穿需独立的光学条件及观测依据。"))

b.append(H("2.3 Vapor pressure, confinement and activation", "2.3 蒸气压、约束与激活", r'activation'))
b.append(P(
    "<strong>Step 10 — Set initial core pressure.</strong> A spherical PFC–carrier interface creates capillary pressure. Add shell-supported overpressure when present. This static reference omits acceleration and shell-rate effects. Those require a dynamic constitutive law.",
    "<strong>步骤 10——规定初始核心压力。</strong> 球形 PFC—载液界面产生毛细压力。存在壳层承压时，加上壳层过压。静态参照忽略加速度与壳层速率效应，后者需动力学本构规律。"))
b.append(E(r'C2-E11', r'p_d\simeq p_c+\frac{2\sigma_{pc}}{a}+\Pi_{\mathrm{shell}},\qquad \frac{2(0.020)}{5\times10^{-6}}=8.00\ \mathrm{kPa},\qquad\frac{2(0.020)}{10^{-7}}=400\ \mathrm{kPa}',
    r'$p_d$ is initial PFC-liquid pressure and $p_c$ carrier pressure (Pa); $a>0$ is PFC-core radius (m); $\sigma_{pc}\ge0$ is PFC–carrier interfacial tension (N m⁻¹), with pc naming those phases; $\Pi_{\mathrm{shell}}$ is shell-supported excess pressure (Pa); $\simeq$ is the static spherical approximation. The numerical interfacial tension 0.020 is a teaching input in N m⁻¹, the radii are in m, and 1 kPa = 1000 Pa.',
    r'$p_d$ 为初始 PFC 液体压力，$p_c$ 为载液压力（Pa）；$a>0$ 为 PFC 核心半径（m）；$\sigma_{pc}\ge0$ 为 PFC–载液界面张力（N m⁻¹），pc 表示这两个相；$\Pi_{\mathrm{shell}}$ 为壳层支撑超压（Pa）；$\simeq$ 表示静态球形近似。数值界面张力 0.020 是教学输入，单位 N m⁻¹；半径单位为 m；1 kPa = 1000 Pa。',
    r'Static capillary and shell-pressure control', {r'type':r'sphere',r'labels':[r'a: PFC-core radius',r'p_d: inside core',r'p_c: aqueous carrier outside',r'σ_pc: PFC–carrier interface',r'Π_shell: shell pressure',r'8 kPa at 5 μm; 400 kPa at 100 nm'], r'notes':[r'PFC-core radius is not the subsequent bubble radius',r'A nanodroplet may need much more local pressure than a micron core']},
    r'The smaller inclusion has a larger capillary contribution at the same tension.', r'界面张力相同时，较小夹杂的毛细压力贡献更大。'))
b.append(P(
    "Specify the compound for every quoted boiling point. NIST entries below describe neat compounds. Tabulated boiling ranges represent different datasets, not formulation uncertainty. Divide molar heat capacity or enthalpy by molar mass for mass-specific values. "+cite(r'r8')+r' '+cite(r'r9')+r' '+cite(r'r15'),
    "每个沸点须注明具体化合物。下列 NIST 条目描述纯物质。表中沸点范围来自不同数据集，并非配方不确定度。摩尔热容或焓除以摩尔质量，得到质量比值。 "+cite(r'r8')+r' '+cite(r'r9')+r' '+cite(r'r15')))
b.append(T(
    [(r'Compound and identity', r'化合物与身份'), (r'Bulk reference', r'体相参照'), (r'Proper scope', r'正确用途')],
    [
        [(r'PFP: C₅F₁₂; CAS 678-26-2; molar mass 0.2880343 kg mol⁻¹', r'PFP：C₅F₁₂；CAS 678-26-2；摩尔质量 0.2880343 kg mol⁻¹'), (r'Normal-boiling entries 302.6–303.2 K; liquid heat-capacity datum 188.3 J mol⁻¹ K⁻¹ at 293 K, giving 653.74 J kg⁻¹ K⁻¹.', r'正常沸点条目 302.6–303.2 K；293 K 液体热容数据为 188.3 J mol⁻¹ K⁻¹，对应 653.74 J kg⁻¹ K⁻¹。'), (r'Compound-specific thermal reference; not a coated-droplet activation law.', r'特定化合物热学参照；不是包覆液滴激活定律。')],
        [(r'PFH: C₆F₁₄; CAS 355-42-0; molar mass 0.3380418 kg mol⁻¹', r'PFH：C₆F₁₄；CAS 355-42-0；摩尔质量 0.3380418 kg mol⁻¹'), (r'Normal-boiling entries 330.3–333 K; vaporization enthalpy 31.5 kJ mol⁻¹ at 316 K, giving 93.18 kJ kg⁻¹.', r'正常沸点条目 330.3–333 K；316 K 汽化焓为 31.5 kJ mol⁻¹，对应 93.18 kJ kg⁻¹。'), (r'Retain temperature and dataset; do not transfer this value to every PFC.', r'保留温度及数据集；不能将此值套用到所有 PFC。')],
        [(r'Water: H₂O; molar mass 0.0180153 kg mol⁻¹', r'水：H₂O；摩尔质量 0.0180153 kg mol⁻¹'), (r'Normal-boiling compilation approximately 373.17 K.', r'正常沸点汇编约为 373.17 K。'), (r'PFC-free thermal comparison at matched temperature and pressure.', r'在相同温度与压力下的不含 PFC 热学参照。')],
    ]))
b.append(P(
    "<strong>Step 11 — Evaluate equilibrium vapor pressure.</strong> Use the NIST Barber–Cady Antoine fit within its temperature range. Pressure divided by one bar makes the logarithm dimensionless. The coefficients are empirical inputs. "+cite(r'r8'),
    "<strong>步骤 11——计算平衡蒸气压。</strong> 在温度适用范围内采用 NIST Barber–Cady Antoine 拟合。压力除以一 bar，使对数自变量无量纲。系数为经验输入。 "+cite(r'r8')))
b.append(E(r'C2-E12', r'\log_{10}\!\left(\frac{p_{\mathrm{sat,PFP}}(T)}{10^5\ \mathrm{Pa}}\right)=4.2063-\frac{1103.454\ \mathrm{K}}{T-39.77\ \mathrm{K}},\qquad282.82\ \mathrm{K}\le T\le337.94\ \mathrm{K}',
    r'$p_{\mathrm{sat,PFP}}(T)$ is bulk equilibrium PFP vapor pressure (Pa), sat labeling saturation; $T$ is absolute temperature in the stated range (K); $\log_{10}$ is the base-ten logarithm. One bar equals $10^5$ Pa. Empirical coefficient 4.2063 is dimensionless; 1103.454 K and 39.77 K have temperature units. The denominator is positive throughout the stated domain.',
    r'$p_{\mathrm{sat,PFP}}(T)$ 为体相平衡 PFP 蒸汽压（Pa），sat 表示饱和；$T$ 为所给范围内的绝对温度（K）；$\log_{10}$ 为常用对数。一巴等于 $10^5$ Pa。经验系数 4.2063 无量纲；1103.454 K 和 39.77 K 具有温度单位。所给范围内分母为正。',
    r'Verified empirical PFP property correlation', {r'type':r'phase',r'labels':[r'T: interface temperature',r'p_sat,PFP: bulk equilibrium vapor pressure',r'282.82–337.94 K: fit domain',r'1 bar = 10⁵ Pa',r'4.2063; 1103.454 K; 39.77 K: coefficients'], r'notes':[r'Liquid and vapor coexist only when inventory and exchange permit',r'This curve is not a laser-fluence threshold']},
    r'The saturation curve concerns an equilibrium state, not automatic activation.', r'饱和曲线描述平衡状态，而不是自动激活。'))
b.append(P(
    "Eq. (C2-E12) gives PFP pressures of 70.60 kPa at 293 K, 103.35 kPa at 303 K, and 204.33 kPa at 323 K. Use water coefficients within their stated interval. They give 2.315 kPa at 293 K and 12.248 kPa at 323 K. These are calculated reference values. "+cite(r'r15'),
    "式（C2-E12）给出 PFP 蒸气压：293 K 时 70.60 kPa，303 K 时 103.35 kPa，323 K 时 204.33 kPa。水系数须在注明温区内使用。所得值为 293 K 时 2.315 kPa、323 K 时 12.248 kPa。这些是计算参照值。 "+cite(r'r15')))
b.append(E(r'C2-E13', r'\log_{10}\!\left(\frac{p_{\mathrm{sat,w}}(T)}{10^5\ \mathrm{Pa}}\right)=\begin{cases}5.40221-1838.675\ \mathrm{K}/(T-31.737\ \mathrm{K}),&273\le T/\mathrm{K}\le303,\\5.20389-1733.926\ \mathrm{K}/(T-39.485\ \mathrm{K}),&304\le T/\mathrm{K}\le333.\end{cases}',
    r'$p_{\mathrm{sat,w}}$ is bulk equilibrium water vapor pressure (Pa), w labeling water; $T$ is temperature (K), restricted to either listed interval; $\log_{10}$ is the base-ten logarithm of pressure relative to one bar ($10^5$ Pa). The leading coefficients are dimensionless; all coefficients multiplied by K have temperature units. $T/\mathrm K$ is the numerical temperature in kelvin. No value is assigned to the 303–304 K gap by these two branches.',
    r'$p_{\mathrm{sat,w}}$ 为体相平衡水蒸汽压（Pa），w 表示水；$T$ 为温度（K），限定在两个所列区间之一；$\log_{10}$ 为相对于一巴（$10^5$ Pa）的压力比值的常用对数。首项系数无量纲；乘以 K 的系数具有温度单位。$T/\mathrm K$ 为以开尔文计的温度数值。这两个分支未给出 303–304 K 间隙的值。',
    r'Verified empirical water property correlations', {r'type':r'phase',r'labels':[r'T: water temperature',r'p_sat,w: water equilibrium pressure',r'273–303 K; 304–333 K: separate branches',r'10⁵ Pa: pressure reference',r'5.40221, 1838.675 K, 31.737 K',r'5.20389, 1733.926 K, 39.485 K'], r'notes':[r'Use the coefficient branch belonging to the temperature',r'The hot PFC and carrier may have different local temperatures']},
    r'Water provides a matched-temperature reference, not a guaranteed vapor reservoir.', r'水提供同温参照，却不是有保证的蒸汽库。'))
b.append(P(
    "At 323 K and 100 kPa carrier pressure, the 5 μm core has 108 kPa liquid pressure. This is below the 204.33 kPa PFP equilibrium reference. The 100 nm core has 500 kPa liquid pressure, above that reference. Bulk driving is positive for the larger core and nonpositive for the smaller core. This control assumes constant tension and zero shell stress. Measured onset temperatures remain unestablished.",
    "在 323 K、载液压力 100 kPa 下，5 μm 核心液压为 108 kPa，低于 204.33 kPa 的 PFP 平衡参照。100 nm 核心液压为 500 kPa，高于该参照。大核心体相驱动为正，小核心驱动不为正。此对照假设张力恒定、壳层应力为零。实测起始温度尚未确立。"))
b.append(P(
    "<strong>Step 12 — Construct nucleus free energy.</strong> Place a vapor nucleus inside liquid PFC. Assume local isothermality and a bulk liquid reservoir. New interface costs tension × area. Favorable vapor gains driving pressure × volume. Use vapor–PFC tension for this internal interface. Eq. (C2-E11) uses PFC–carrier tension at the outer interface.",
    "<strong>步骤 12——建立汽核自由能。</strong> 汽核位于液态 PFC 内部。假设局部等温与体相液体储库。新界面消耗张力 × 面积，有利蒸气获得驱动压差 × 体积。内部界面采用蒸气—PFC 张力。式（C2-E11）外界面采用 PFC—载液张力。"))
b.append(E(r'C2-E14', r'\Delta p_n=p_{\mathrm{sat,PFC}}(T_i)-p_d,\qquad W(r_n)=4\pi\sigma_{vp}r_n^2-\frac{4\pi}{3}\Delta p_n r_n^3',
    r'$\Delta p_n$ is vapor-nucleation driving pressure (Pa), n labeling nucleation; $p_{\mathrm{sat,PFC}}(T_i)$ is bulk PFC saturation pressure at local interface temperature $T_i$ (Pa and K); $p_d$ is PFC-liquid pressure (Pa); $W(r_n)$ is nucleus formation free energy (J); $r_n\ge0$ is vapor-nucleus radius (m); $\sigma_{vp}>0$ is vapor–PFC tension (N m⁻¹), vp naming the interface; $\pi$ is the circular constant. The model assumes fixed $T_i,p_d$, and $r_n$ small compared with the PFC core.',
    r'$\Delta p_n$ 为汽化成核驱动压差（Pa），n 表示成核；$p_{\mathrm{sat,PFC}}(T_i)$ 为局部界面温度 $T_i$ 下的体相 PFC 饱和蒸汽压（Pa 和 K）；$p_d$ 为 PFC 液体压力（Pa）；$W(r_n)$ 为汽核形成自由能（J）；$r_n\ge0$ 为汽核半径（m）；$\sigma_{vp}>0$ 为蒸汽–PFC 张力（N m⁻¹），vp 表示该界面；$\pi$ 为圆周率。模型假设 $T_i,p_d$ 固定，且 $r_n$ 远小于 PFC 核心。',
    r'Classical homogeneous capillarity approximation', {r'type':r'nucleation',r'labels':[r'r_n: nucleus radius inside PFC',r'σ_vp: newly created vapor–PFC interface',r'T_i: local nucleus temperature',r'p_d: surrounding PFC liquid',r'p_sat,PFC: equilibrium vapor reference',r'Δp_n: volume driving',r'W: surface cost minus volume gain',r'π: spherical geometry'], r'notes':[r'The outer PFC–carrier tension is a different interface',r'The whole core cannot be treated as an infinite liquid reservoir']},
    r'The barrier belongs to creating a new internal vapor interface.', r'势垒来自生成新的内部蒸汽界面。'))
b.append(P(
    "<strong>Step 13 — Find the critical branch.</strong> Differentiate both radius powers. For positive driving, divide the nonzero-radius bracket by positive driving pressure. The second derivative is negative at the critical radius. It is a barrier maximum. For nonpositive driving, the derivative stays positive at positive radius. No positive critical-radius branch exists in that case.",
    "<strong>步骤 13——求临界分支。</strong> 对两个半径幂求导。正驱动时，将非零半径括号除以正驱动压差。临界半径处二阶导数为负，对应势垒最大值。驱动不为正时，所有正半径处导数为正，因此不存在正临界半径分支。"))
b.append(E(r'C2-E15', r'\begin{aligned}\frac{dW}{dr_n}&=8\pi\sigma_{vp}r_n-4\pi\Delta p_n r_n^2=4\pi r_n(2\sigma_{vp}-\Delta p_n r_n),\\r_*&=2\sigma_{vp}/\Delta p_n\quad(\Delta p_n>0),\\\left.\frac{d^2W}{dr_n^2}\right|_{r_*}&=8\pi\sigma_{vp}-8\pi\Delta p_n r_*=-8\pi\sigma_{vp}<0.\end{aligned}',
    r'$W$ is nucleus free energy (J); $r_n>0$ is nucleus radius (m); $\sigma_{vp}>0$ is vapor–PFC interfacial tension (N m⁻¹); $\Delta p_n$ is fixed driving pressure (Pa); $r_*$ is the positive critical radius (m), with star labeling the stationary point and requiring $\Delta p_n>0$; $d/dr_n$ is radius differentiation, $|_{r_*}$ denotes evaluation there, and $\pi$ is the circular constant. The first derivative has units J m⁻¹ and the second J m⁻².',
    r'$W$ 为汽核自由能（J）；$r_n>0$ 为汽核半径（m）；$\sigma_{vp}>0$ 为蒸汽–PFC 界面张力（N m⁻¹）；$\Delta p_n$ 为固定驱动压差（Pa）；$r_*$ 为正临界半径（m），星号标记驻点，且要求 $\Delta p_n>0$；$d/dr_n$ 为对半径求导，$|_{r_*}$ 表示在该点求值，$\pi$ 为圆周率。一阶导数单位为 J m⁻¹，二阶导数为 J m⁻²。',
    r'Derived critical radius and branch check', {r'type':r'nucleation',r'labels':[r'r_n: horizontal radius coordinate',r'W: free-energy curve',r'r_*: maximum for Δp_n > 0',r'σ_vp, Δp_n: barrier controls',r'dW/dr_n = 0 at r_*',r'd²W/dr_n² < 0',r'π: spherical factors'], r'notes':[r'Below r_* the surface term drives shrinkage in the static control',r'No positive critical radius when Δp_n ≤ 0']},
    r'The stationary point is a maximum, not a stable equilibrium nucleus.', r'该驻点是最大值，不是稳定平衡汽核。'))
b.append(P(
    "<strong>Step 14 — Evaluate the barrier.</strong> Substitute the squared and cubed critical radius. Subtract the coefficients explicitly. Increasing driving pressure lowers the barrier. Finite positive driving and tension leave a positive barrier.",
    "<strong>步骤 14——计算势垒。</strong> 代入临界半径的平方与三次方，并明确相减系数。增大驱动压差会降低势垒。有限正驱动与正张力仍给出正势垒。"))
b.append(E(r'C2-E16', r'\begin{aligned}W_*&=4\pi\sigma_{vp}\frac{4\sigma_{vp}^2}{\Delta p_n^2}-\frac{4\pi}{3}\Delta p_n\frac{8\sigma_{vp}^3}{\Delta p_n^3}\\&=\left(16-\frac{32}{3}\right)\frac{\pi\sigma_{vp}^3}{\Delta p_n^2}=\frac{16\pi\sigma_{vp}^3}{3\Delta p_n^2}.\end{aligned}',
    r'$W_*=W(r_*)$ is critical-nucleus free-energy barrier (J), with star labeling the critical value; $\sigma_{vp}>0$ is vapor–PFC interfacial tension (N m⁻¹); $\Delta p_n>0$ is driving pressure (Pa); $\pi$ is the circular constant; superscripts 2 and 3 are powers. This result inherits the homogeneous, locally isothermal, small-nucleus assumptions.',
    r'$W_*=W(r_*)$ 为临界汽核自由能势垒（J），星号标记临界值；$\sigma_{vp}>0$ 为蒸汽–PFC 界面张力（N m⁻¹）；$\Delta p_n>0$ 为驱动压差（Pa）；$\pi$ 为圆周率；上标 2、3 表示幂。该结果继承均匀成核、局部等温及小汽核假设。',
    r'Derived homogeneous barrier height', {r'type':r'nucleation',r'labels':[r'W_*: free-energy maximum',r'r_*: critical radius',r'σ_vp³: strong tension dependence',r'Δp_n²: driving-pressure dependence',r'π: spherical geometry'], r'notes':[r'Surface energy and displaced-volume contribution evaluated at r_*',r'A positive driving pressure still leaves a finite barrier']},
    r'Positive superheat driving does not make the nucleation barrier vanish.', r'正的过热驱动力并不会使成核势垒消失。'))
b.append(P(
    "The barrier unit is $\\mathrm{(N/m)^3/Pa^2=N\\,m=J}$. Tension/pressure gives critical-radius units m. A nucleus comparable to core size violates the reservoir approximation. Surfaces, defects, dissolved gas and wetting can favor heterogeneous nucleation. An imposed seed defines post-nucleation dynamics. Onset prediction then remains unestablished.",
    "势垒单位为 $\\mathrm{(N/m)^3/Pa^2=N\\,m=J}$。张力／压力给出临界半径单位 m。汽核接近核心尺寸时，储库近似失效。表面、缺陷、溶解气体与润湿可促进异质成核。人为种子规定成核后的动力学，起始预测仍未确立。"))
b.append(P(
    "<strong>Step 15 — Derive activation probability.</strong> Assume independent Poisson events. In a short interval, survival loses event expectation × current survival. Integrate the logarithmic derivative from initial survival one. Spatially and temporally varying rates fit this model. The rate itself requires a separate law. Use measured activation behavior when homogeneous nucleation is unsuitable.",
    "<strong>步骤 15——推导激活概率。</strong> 假设独立 Poisson 事件。短时间内，存活概率减少量为事件期望数乘当前存活概率。从初始存活概率一积分对数导数。模型允许速率随时空变化。速率本身需独立规律。均质成核不适用时，应采用测量激活规律。"))
b.append(E(r'C2-E17', r'\begin{aligned}\Lambda(t)&=\int_{V_d(t)}J(T, p)\,dV,\qquad\frac{dS}{dt}=-\Lambda(t)S,\qquad S(0)=1,\\\ln S(t)&=-\int_0^t\Lambda(t^{\prime})\,dt^{\prime},\qquad P_{\mathrm{act}}(t)=1-S(t)=1-e^{-\int_0^t\int_{V_d(t^{\prime})}J(T,p)\,dV\,dt^{\prime}}.\end{aligned}',
    r'$J(T,p)\ge0$ is prescribed nucleation rate (m⁻³ s⁻¹) at local temperature $T$ (K) and pressure $p$ (Pa); $V_d(t)$ denotes the remaining liquid-core region and its volume (m³), d labeling droplet; $\Lambda(t)$ is total event rate (s⁻¹); $S(t)$ is no-event survival probability and $P_{\mathrm{act}}$ activation probability (dimensionless); $t\ge0,t^{\prime}$ are time and dummy time (s); $dV$ is volume element (m³); $d/dt$, $\int$, $\ln$, and $e^x$ denote differentiation, integration, natural logarithm, and exponential. The derivation assumes finite integrated nonnegative rate and independent Poisson events.',
    r'$J(T,p)\ge0$ 为给定的成核速率（m⁻³ s⁻¹），取决于局部温度 $T$（K）与压力 $p$（Pa）；$V_d(t)$ 表示剩余液核区域及其体积（m³），d 表示液滴；$\Lambda(t)$ 为总事件速率（s⁻¹）；$S(t)$ 为未发生事件的概率，$P_{\mathrm{act}}$ 为激活概率（无量纲）；$t\ge0,t^{\prime}$ 为时间及哑时间（s）；$dV$ 为体积元（m³）；$d/dt$、$\int$、$\ln$、$e^x$ 表示求导、积分、自然对数和指数函数。推导要求积分非负速率有限，且事件满足独立 Poisson 模型。',
    r'Derived probability under a prescribed Poisson rate', {r'type':r'nucleation',r'labels':[r'V_d(t): remaining liquid region',r'T, p: local state',r'J: events per volume per time',r'Λ(t): integrated event rate',r'S(0) = 1; S(t): survival',r'P_act = 1 − S',r't, t′, dV: integration domain'], r'notes':[r'Integrate the hot, pressurized region rather than only its average temperature',r'An absent event can mean low probability, not impossibility']},
    r'Activation probability requires the rate and the time spent in the activating state.', r'激活概率需要速率及处于可激活状态的时长。'))

b.append(H("2.4 Phase mass and energy balances", "2.4 相质量与能量平衡", r'inventory'))
b.append(P(
    "<strong>Step 16 — Conserve PFC inventory.</strong> Initial mass equals liquid density × core volume. Without external supply, liquid, vapor, dissolved and escaped PFC sum to that mass. Escaped mass is cumulative. It differs from vapor retained inside the bubble. Water supplies no additional PFC.",
    "<strong>步骤 16——PFC 物质量守恒。</strong> 初始质量等于液体密度 × 核心体积。无外部供给时，液体、蒸气、溶解及逸出 PFC 之和等于初始质量。逸出质量按累计记账，与气泡内保留蒸气不同。水不能补充 PFC。"))
b.append(E(r'C2-E18', r'm_{\mathrm{PFC},0}=\frac{4\pi}{3}\rho_da_0^3,\qquad m_l+m_v+m_{\mathrm{diss}}+m_{\mathrm{esc}}=m_{\mathrm{PFC},0},\qquad 0\le m_v\le m_{\mathrm{PFC},0}',
    r'$m_{\mathrm{PFC},0}$ is initial PFC mass (kg), 0 labeling the initial state; $\rho_d>0$ is initial PFC-liquid density (kg m⁻³), d labeling droplet; $a_0>0$ is initial core radius (m); $m_l,m_v,m_{\mathrm{diss}},m_{\mathrm{esc}}\ge0$ are remaining liquid PFC, in-domain vapor PFC, dissolved PFC, and cumulative escaped PFC (kg); the l, v, diss, and esc labels name those compartments; $\pi$ is the circular constant. The bound assumes no subsequent PFC supply.',
    r'$m_{\mathrm{PFC},0}$ 为初始 PFC 质量（kg），0 表示初始状态；$\rho_d>0$ 为初始 PFC 液体密度（kg m⁻³），d 表示液滴；$a_0>0$ 为初始核心半径（m）；$m_l,m_v,m_{\mathrm{diss}},m_{\mathrm{esc}}\ge0$ 为剩余液态 PFC、域内 PFC 蒸汽、溶解 PFC 及累计逸出 PFC（kg）；l、v、diss、esc 分别标记这些部分；$\pi$ 为圆周率。质量上界假设后续没有 PFC 供应。',
    r'Exact compound-mass ledger under the stated closed supply', {r'type':r'phase',r'labels':[r'a₀, ρ_d: original liquid core',r'm_PFC,0: fixed initial inventory',r'm_l: liquid remainder',r'm_v: bubble vapor',r'm_diss: carrier dissolution',r'm_esc: mass crossing outer boundary',r'π: initial sphere geometry'], r'notes':[r'Mass can change compartment without being created',r'Once venting begins, in-domain mass can decrease']},
    r'The compound ledger survives expansion, condensation, dissolution, and venting.', r'化合物账目在膨胀、凝结、溶解及排气过程中均成立。'))
b.append(P(
    "<strong>Step 17 — Identify the phase-change surface.</strong> Integrate species flux over its contacted interface. Full spherical area requires full species contact and uniform flux. Residual PFC in water can have a smaller vaporization surface.",
    "<strong>步骤 17——确定相变表面。</strong> 在组分实际接触的界面上积分通量。采用完整球面面积需该组分接触全表面且通量均匀。水中残留 PFC 可具有更小汽化表面。"))
b.append(E(r'C2-E19', r'\left.\dot m_{v,s}\right|_{\mathrm{phase}}=\int_{\Gamma_s}j_s\,dA,\qquad \left.\dot m_{v,s}\right|_{\mathrm{phase}}=4\pi R^2j_s\quad\text{only for uniform complete spherical contact}',
    r'$m_{v,s}$ is vapor mass of species $s$ (kg), where $s$ labels a specified species such as PFC or water; a dot is a time derivative (kg s⁻¹); the phase label isolates the phase-change contribution, excluding escape and dissolution; $j_s$ is signed liquid-to-vapor mass flux (kg m⁻² s⁻¹); $\Gamma_s$ is the species-contacting interface; $dA$ is its area element (m²); $R>0$ is spherical interface radius (m) only in the special second formula; $\pi$ is the circular constant; $\int$ is surface integration.',
    r'$m_{v,s}$ 为组分 $s$ 的蒸汽质量（kg），$s$ 标记 PFC 或水等明确组分；上点表示时间导数（kg s⁻¹）；phase 标记单独的相变贡献，不含逸出与溶解；$j_s$ 为带符号液到汽质量通量（kg m⁻² s⁻¹）；$\Gamma_s$ 为该组分接触的界面；$dA$ 为面积元（m²）；$R>0$ 仅在第二个特殊式中表示球形界面半径（m）；$\pi$ 为圆周率；$\int$ 为面积积分。',
    r'Species phase-mass balance', {r'type':r'phase',r'labels':[r'Γ_s: actual species interface',r'j_s: liquid → vapor',r'm_v,s, ṁ_v,s: vapor inventory and rate',r'R: complete bubble radius only when applicable',r'dA: contacted surface patch',r'π: full-sphere special case'], r'notes':[r'PFC may occupy only a residual inclusion',r'Do not give every species the whole bubble area automatically']},
    r'A bubble surface and a PFC evaporation surface need not be identical.', r'气泡表面与 PFC 蒸发表面未必相同。'))
b.append(P(
    "<strong>Step 18 — Derive velocity slip.</strong> A single-component phase boundary has equal mass flux on both sides. Inside a bubble, the liquid-to-vapor normal points inward. Project liquid velocity minus interface velocity onto that normal. The result is wall speed minus radial liquid speed. Solve for liquid speed. Equating potential-flow speed to wall speed then assumes small slip.",
    "<strong>步骤 18——推导速度滑移。</strong> 单组分相界面两侧质量通量相等。气泡内液体指向蒸气的法向朝内。将液体速度减界面速度投影至该法向，得到壁面速度减径向液速。由此求液速。将势流液速等同壁速需要小滑移假设。"))
b.append(E(r'C2-E20', r'\begin{aligned}j_s&=\rho_l(\boldsymbol u_l-\boldsymbol v_\Gamma)\cdot\boldsymbol n=\rho_v(\boldsymbol u_v-\boldsymbol v_\Gamma)\cdot\boldsymbol n,\\\boldsymbol n&=-\boldsymbol e_r,\quad\boldsymbol v_\Gamma=\dot R\boldsymbol e_r,\quad j_s=\rho_l[\dot R-u_l(R)],\\u_l(R)&=\dot R-j_s/\rho_l.\end{aligned}',
    r'$j_s$ is single-component phase mass flux (kg m⁻² s⁻¹), s labeling that component; $\rho_l,\rho_v>0$ are adjacent liquid and vapor densities (kg m⁻³); $\boldsymbol u_l,\boldsymbol u_v$ are their velocities (m s⁻¹); $\boldsymbol v_\Gamma$ is interface velocity (m s⁻¹); $\boldsymbol n$ is unit normal liquid→vapor and $\boldsymbol e_r$ outward radial unit vector (dimensionless); $R>0$ is bubble radius (m), $\dot R$ its time derivative (m s⁻¹); $u_l(R)$ is outward radial liquid velocity at the interface (m s⁻¹); $\cdot$ is a vector dot product.',
    r'$j_s$ 为单组分相变质量通量（kg m⁻² s⁻¹），s 标记该组分；$\rho_l,\rho_v>0$ 为邻接液体与蒸汽密度（kg m⁻³）；$\boldsymbol u_l,\boldsymbol u_v$ 为两侧速度（m s⁻¹）；$\boldsymbol v_\Gamma$ 为界面速度（m s⁻¹）；$\boldsymbol n$ 为液→汽单位法向，$\boldsymbol e_r$ 为向外径向单位向量（无量纲）；$R>0$ 为气泡半径（m），$\dot R$ 为其时间导数（m s⁻¹）；$u_l(R)$ 为界面处向外径向液速（m s⁻¹）；$\cdot$ 为向量点积。',
    r'Exact single-component interface mass jump', {r'type':r'phase',r'labels':[r'R, Ṙ: moving bubble surface',r'e_r: outward radial direction',r'n = −e_r: liquid → vapor',r'u_l(R), u_l: outside-liquid motion',r'u_v: vapor-side motion',r'v_Γ: interface motion',r'ρ_l, ρ_v: adjoining densities',r'j_s: evaporation through interface'], r'notes':[r'Positive j_s makes liquid speed smaller than outward wall speed',r'For mixtures, species diffusion augments the component fluxes']},
    r'The interface need not move at the same speed as the adjacent liquid.', r'界面不必以邻接液体的速度运动。'))
b.append(P(
    "Require $|j_s|/\\rho_l$ below a relevant liquid or interface speed scale. At a turning point, use finite event speed instead of zero wall speed. Strong evaporation can add recoil stress. Check it before reusing Chapter 1’s simple wall stress. Mixtures require species diffusion, composition conditions and common mass balance.",
    "要求 $|j_s|/\\rho_l$ 小于相关液体或界面速率尺度。转折点处采用有限事件速率，避免除以零壁速。强蒸发可增加反冲应力。复用第一章简单壁面应力前须检验反冲。混合物需要组分扩散、组成条件和共同质量平衡。"))
b.append(P(
    "<strong>Step 19 — Derive the Stefan sign.</strong> Omit surface heat storage and kinetic/mechanical jump corrections. Liquid-side conductive influx minus vapor-side outflux supplies phase-change enthalpy. Evaluate both enthalpies at matching temperature and reference conventions. Reversing heat supply gives negative flux. Condensation then releases latent enthalpy.",
    "<strong>步骤 19——推导 Stefan 符号。</strong> 忽略界面热储存及动能、力学跳跃修正。液侧传导流入减汽侧流出，供给相变焓。两侧焓采用一致温度与参考约定。反转供热会产生负通量，凝结释放潜焓。"))
b.append(E(r'C2-E21', r'L_{v,s}=h_{v,s}-h_{l,s}>0,\qquad j_sL_{v,s}=(\boldsymbol q_l-\boldsymbol q_v)\cdot\boldsymbol n,\qquad\boldsymbol q_\eta=-k_\eta\nabla T_\eta\quad(\eta=l,v)',
    r'$L_{v,s}>0$ is latent enthalpy per species mass (J kg⁻¹); $h_{v,s},h_{l,s}$ are vapor and liquid specific enthalpies of species s at the interface (J kg⁻¹); $j_s$ is signed evaporation flux (kg m⁻² s⁻¹); $\boldsymbol q_l,\boldsymbol q_v$ are conductive heat fluxes on liquid and vapor sides (W m⁻²); $\boldsymbol n$ points liquid→vapor; $\eta\in\{l,v\}$ labels phase; $k_\eta$ and $T_\eta$ are conductivity (W m⁻¹ K⁻¹) and temperature (K); $\nabla$ is spatial gradient (m⁻¹); $\cdot$ is a vector dot product. All terms in the heat jump have units W m⁻².',
    r'$L_{v,s}>0$ 为单位组分质量的潜焓（J kg⁻¹）；$h_{v,s},h_{l,s}$ 为界面处组分 s 的蒸汽与液体比焓（J kg⁻¹）；$j_s$ 为带符号蒸发通量（kg m⁻² s⁻¹）；$\boldsymbol q_l,\boldsymbol q_v$ 为液、汽两侧传导热通量（W m⁻²）；$\boldsymbol n$ 从液指向汽；$\eta\in\{l,v\}$ 表示相；$k_\eta,T_\eta$ 为导热系数（W m⁻¹ K⁻¹）与温度（K）；$\nabla$ 为空间梯度（m⁻¹）；$\cdot$ 为向量点积。热跳跃式各项单位均为 W m⁻²。',
    r'Reduced interfacial energy jump and Fourier law', {r'type':r'phase',r'labels':[r'n: liquid → vapor',r'q_l: heat arriving from liquid',r'q_v: heat leaving into vapor',r'j_s: phase mass flux',r'h_l,s → h_v,s: enthalpy change',r'L_v,s: latent requirement',r'k_l, k_v; T_l, T_v: thermal fields',r'η = l or v; ∇: local gradient'], r'notes':[r'Evaporation j_s > 0 consumes latent enthalpy',r'Condensation j_s < 0 supplies heat to surrounding material']},
    r'The liquid-to-vapor normal fixes the signs of heat and phase flux.', r'液到汽法向确定热通量及相变通量符号。'))
b.append(P(
    "For a sign control, prescribe normal heat supply 0.95 MW m⁻², zero vapor-side loss, and latent enthalpy 95 kJ kg⁻¹. Stefan flux is 10 kg m⁻² s⁻¹. With adjacent density 1000 kg m⁻³, slip is 0.010 m s⁻¹. With PFC density 1630 kg m⁻³, slip is 0.006135 m s⁻¹. Density belongs to the actual evaporating phase. Reversing heat reverses flux and slip. This checks units and sign. Actual nanoemulsion interface state remains unestablished.",
    "符号对照给定法向供热 0.95 MW m⁻²、汽侧损失为零、潜焓 95 kJ kg⁻¹。Stefan 通量为 10 kg m⁻² s⁻¹。邻接密度取 1000 kg m⁻³ 时，滑移为 0.010 m s⁻¹。PFC 密度取 1630 kg m⁻³ 时，滑移为 0.006135 m s⁻¹。密度应属于实际蒸发相。反转供热会反转通量与滑移。这检验单位与符号。实际纳米乳液界面状态尚未确立。"))
b.append(P(
    "<strong>Step 20 — Apply the bubble first law.</strong> Use a uniform-state open vapor control volume. Incoming mass carries enthalpy, including entry flow work. Expansion performs work on the surroundings. Count conductive heat separately. Omit resolved internal kinetic energy and surface storage. Outgoing mass carries its own boundary enthalpy. Each flux requires a consistent boundary state.",
    "<strong>步骤 20——应用气泡第一定律。</strong> 将蒸气作为均匀状态开放控制体。流入质量携带焓，包括进入所需流动功。膨胀对外做功，传导热单独计入。忽略解析内部动能和界面储存。流出质量携带其边界焓。各通量均需一致边界状态。"))
b.append(E(r'C2-E22', r'\dot U_b=\dot Q_b-p_b\dot V_b+\sum_{s=1}^{N_s}h_{v,s}\dot m_{v,s},\qquad V_b=\frac{4\pi}{3}R^3,\qquad\dot V_b=4\pi R^2\dot R',
    r'$U_b$ is bubble internal energy (J); $\dot Q_b$ is net conductive heat into the bubble (W), excluding transported mass enthalpy; $p_b$ is uniform absolute bubble pressure (Pa); $V_b$ is bubble volume (m³); $R>0$ is radius in the spherical control (m); $h_{v,s}$ is boundary specific vapor enthalpy of species s (J kg⁻¹); $\dot m_{v,s}$ is its signed net mass-entry rate (kg s⁻¹); $s=1,\ldots,N_s$ indexes the $N_s$ species, a dimensionless count; $\sum$ is summation; a dot is a time derivative, and $\pi$ is the circular constant. Distinct entry/exit states require distinct summed boundary terms.',
    r'$U_b$ 为气泡内能（J）；$\dot Q_b$ 为进入气泡的净传导热（W），不含随质量输运的焓；$p_b$ 为均匀绝对气泡压力（Pa）；$V_b$ 为气泡体积（m³）；$R>0$ 为球形参照的半径（m）；$h_{v,s}$ 为组分 s 的边界蒸汽比焓（J kg⁻¹）；$\dot m_{v,s}$ 为其带符号净流入质量速率（kg s⁻¹）；$s=1,\ldots,N_s$ 遍历 $N_s$ 个组分，$N_s$ 为无量纲数量；$\sum$ 为求和；上点为时间导数，$\pi$ 为圆周率。不同流入／流出状态要求分别求和其边界项。',
    r'Uniform-state open-bubble first-law model', {r'type':r'energy',r'labels':[r'U_b: vapor energy storage',r'Q̇_b: conductive heat only',r'p_b, V_b, V̇_b: pressure work',r'R, Ṙ: bubble geometry and speed',r'h_v,s, ṁ_v,s: mass enthalpy entry',r's = 1…N_s: species ledger',r'π: spherical volume'], r'notes':[r'Expansion removes energy through p_b V̇_b',r'Do not add a second latent-heat source to transported vapor enthalpy']},
    r'Mass enthalpy and conductive heat are different terms in the bubble ledger.', r'质量焓与传导热是气泡账目中的不同项。'))
b.append(P(
    "<strong>Step 21 — Expand the temperature derivative.</strong> Assume common temperature and ideal species energies dependent on temperature. Differentiate each mass × specific-energy product. Constant-volume specific heat is the specific-energy derivative. Subtract bulk internal energy from boundary enthalpy. This gives pressure flow work when both states match. Different entry temperature adds a sensible internal-energy difference. The expansion retains changing vapor mass explicitly.",
    "<strong>步骤 21——展开温度导数。</strong> 假设共同温度，理想组分内能随温度变化。对各质量 × 比内能乘积求导。定容比热等于比内能温度导数。边界焓减去体相比内能，在状态一致时给出压力流动功。入口温度不同时，还包含显内能差。展开式明确保留蒸气质量变化。"))
b.append(E(r'C2-E23', r'\begin{aligned}U_b&=\sum_{s=1}^{N_s}m_{v,s}e_s(T_b),\qquad c_{v,s}=de_s/dT_b,\\\dot U_b&=\left(\sum_s m_{v,s}c_{v,s}\right)\dot T_b+\sum_s e_s\dot m_{v,s},\\\left(\sum_s m_{v,s}c_{v,s}\right)\dot T_b&=\dot Q_b-p_b\dot V_b+\sum_s(h_{v,s}-e_s)\dot m_{v,s}.\end{aligned}',
    r'$U_b$ is internal energy (J); $m_{v,s}$ is species vapor mass (kg); $e_s(T_b)$ is specific internal energy using a consistent reference (J kg⁻¹); $T_b$ is common bubble temperature (K); $c_{v,s}=de_s/dT_b$ is constant-volume specific heat (J kg⁻¹ K⁻¹); $h_{v,s}$ is actual boundary specific enthalpy (J kg⁻¹); $\dot Q_b$ is conductive heat input (W); $p_b,V_b$ are pressure (Pa) and volume (m³); $s=1,\ldots,N_s$ is species index and $\sum_s$ sums that range; a dot denotes a time derivative; $d/dT_b$ is temperature differentiation. Boundary temperature may differ from $T_b$ and must then be used in $h_{v,s}$.',
    r'$U_b$ 为内能（J）；$m_{v,s}$ 为组分蒸汽质量（kg）；$e_s(T_b)$ 为采用一致参考的比内能（J kg⁻¹）；$T_b$ 为共同气泡温度（K）；$c_{v,s}=de_s/dT_b$ 为定容比热（J kg⁻¹ K⁻¹）；$h_{v,s}$ 为实际边界比焓（J kg⁻¹）；$\dot Q_b$ 为传导热输入（W）；$p_b,V_b$ 为压力（Pa）与体积（m³）；$s=1,\ldots,N_s$ 为组分指标，$\sum_s$ 对该范围求和；上点表示时间导数；$d/dT_b$ 为温度求导。边界温度可不同于 $T_b$，此时 $h_{v,s}$ 必须使用边界温度。',
    r'Product-rule derivation of thermal closure', {r'type':r'energy',r'labels':[r'T_b, Ṫ_b: common vapor temperature',r'm_v,s, ṁ_v,s: changing species mass',r'e_s, c_v,s: internal-energy storage',r'h_v,s: boundary enthalpy',r'U_b: total stored energy',r'Q̇_b: conduction',r'p_b V̇_b: work',r's = 1…N_s: summation'], r'notes':[r'The product rule includes both temperature and mass changes',r'Consistent energy references preserve the balance']},
    r'A variable vapor mass makes a fixed-mass polytropic shortcut conditional.', r'蒸汽质量变化，使固定质量多方捷径只能有条件成立。'))
b.append(P(
    "Use consistent enthalpy references in Stefan and bubble balances. Interface heat creates the specified incoming vapor enthalpy. Adding another latent source to Eq. (C2-E22) duplicates that conversion. Fixed-mass adiabatic expansion lowers bubble energy. Cooling and condensation can lower pressure. Slow mass exchange can retain vapor and cushion collapse. Dissolution, permanent gas and escape need separate balances.",
    "Stefan 与气泡平衡采用一致焓参考。界面热产生指定的流入蒸气焓。再向式（C2-E22）加入潜热源会重复计入转化。固定质量绝热膨胀降低气泡能量。冷却与凝结可降低压力。质量交换慢时可保留蒸气并缓冲塌缩。溶解、非凝结气体及逸出需独立平衡。"))
b.append(P(
    "Specify nonzero seed volume, species masses and temperature after nucleation. Also specify initial interface shape and velocity. All seeds must satisfy inventory and energy balances. Onset probability leaves these states unresolved. Before vapor appears, use liquid heating and activation equations. Zero vapor heat capacity excludes starting with the bubble temperature equation.",
    "成核后须指定非零种子体积、组分质量和温度，以及初始界面形状和速度。所有种子均须满足物质与能量平衡。起始概率不能确定这些状态。蒸气出现前采用液体加热及激活方程。蒸气热容为零时，不能用气泡温度方程启动。"))
b.append(P(
    "<strong>Step 22 — Close pressure with an EOS.</strong> In a dilute ideal mixture, each partial pressure follows species moles, common temperature and volume. Sum all species, including permanent gas. High-density compression requires a real-fluid or mixture EOS. Antoine saturation and a fixed polytropic exponent leave that state closure unresolved.",
    "<strong>步骤 22——用状态方程闭合压力。</strong> 稀薄理想混合物中，各分压由组分摩尔数、共同温度和体积决定。求和所有组分，包括非凝结气体。高密度压缩需要真实流体或混合物状态方程。Antoine 饱和关系与固定多方指数不能闭合该状态。"))
b.append(E(r'C2-E24', r'p_{v,s}V_b=\frac{m_{v,s}}{M_s}R_uT_b,\qquad p_b=\sum_{s=1}^{N_s}p_{v,s},\qquad p_b=\mathcal P(\rho_b,e_b,\boldsymbol Y)\quad\text{for a stated real-mixture EOS}',
    r'$p_{v,s}$ is ideal partial pressure of species s (Pa), v naming the vapor-domain component; $V_b>0$ is bubble volume (m³); $m_{v,s}\ge0$ is its mass (kg); $M_s>0$ is molar mass (kg mol⁻¹); $R_u=8.314462618$ J mol⁻¹ K⁻¹ is the universal gas constant; $T_b>0$ is bulk temperature (K); $p_b$ is total pressure (Pa); $s=1,\ldots,N_s$ indexes all components including permanent gas; $\sum$ is summation. $\mathcal P$ is a specified equation-of-state function, $\rho_b$ mixture density (kg m⁻³), $e_b$ specific internal energy (J kg⁻¹), and $\boldsymbol Y$ the species mass-fraction vector (dimensionless, entries summing to one); EOS means equation of state.',
    r'$p_{v,s}$ 为组分 s 的理想分压（Pa），v 标记蒸汽域组分；$V_b>0$ 为气泡体积（m³）；$m_{v,s}\ge0$ 为其质量（kg）；$M_s>0$ 为摩尔质量（kg mol⁻¹）；$R_u=8.314462618$ J mol⁻¹ K⁻¹ 为通用气体常数；$T_b>0$ 为体相温度（K）；$p_b$ 为总压力（Pa）；$s=1,\ldots,N_s$ 遍历包含永久气体的所有组分；$\sum$ 为求和。$\mathcal P$ 为明确的状态方程函数，$\rho_b$ 为混合物密度（kg m⁻³），$e_b$ 为比内能（J kg⁻¹），$\boldsymbol Y$ 为组分质量分数向量（无量纲，各分量之和为一）；EOS 指状态方程。',
    r'Ideal-mixture constitutive control and required refinement', {r'type':r'phase',r'labels':[r'm_v,s, M_s: species mole inventory',r'T_b: common temperature',r'V_b: finite bubble volume',r'p_v,s: component pressure',r'p_b: total mixture pressure',r'R_u: gas constant',r'ρ_b, e_b, Y: real-mixture state',r's = 1…N_s; P: EOS function'], r'notes':[r'Permanent gas remains after condensable vapor is removed',r'Dense compression requires a calibrated EOS']},
    r'The pressure responds to species masses, temperature, and changing volume.', r'压力响应组分质量、温度及体积变化。'))
b.append(P(
    "<strong>Step 23 — Separate pressure-change terms.</strong> Require positive species mass, temperature, pressure and volume. Take the ideal-law logarithm and differentiate. The terms represent mass change, temperature change and compression. At zero species mass, use Eq. (C2-E24) directly.",
    "<strong>步骤 23——分离压力变化项。</strong> 要求组分质量、温度、压力及体积为正。对理想定律取对数并求导，分离质量变化、温度变化及压缩项。组分质量为零时，直接采用式（C2-E24）。"))
b.append(E(r'C2-E25', r'\frac{\dot p_{v,s}}{p_{v,s}}=\frac{\dot m_{v,s}}{m_{v,s}}+\frac{\dot T_b}{T_b}-\frac{\dot V_b}{V_b}=\frac{\dot m_{v,s}}{m_{v,s}}+\frac{\dot T_b}{T_b}-3\frac{\dot R}{R}\quad\text{(sphere)}',
    r'$p_{v,s}>0$ is species partial pressure (Pa); $m_{v,s}>0$ is its vapor-domain mass (kg), s labeling species; $T_b>0$ is bubble temperature (K); $V_b>0$ is volume (m³); $R>0$ is radius for a spherical bubble (m); a dot is a time derivative. Every ratio has units s⁻¹; the final equality uses $V_b=4\pi R^3/3$ and is restricted to spherical geometry.',
    r'$p_{v,s}>0$ 为组分分压（Pa）；$m_{v,s}>0$ 为其蒸汽域质量（kg），s 表示组分；$T_b>0$ 为气泡温度（K）；$V_b>0$ 为体积（m³）；$R>0$ 为球形气泡半径（m）；上点表示时间导数。各比值单位均为 s⁻¹；最后一个等式使用 $V_b=4\pi R^3/3$，仅限球形几何。',
    r'Derived ideal-pressure evolution identity', {r'type':r'phase',r'labels':[r'p_v,s, ṗ_v,s: partial pressure change',r'm_v,s, ṁ_v,s: evaporation or loss',r'T_b, Ṫ_b: heating or cooling',r'V_b, V̇_b: geometric expansion',r'R, Ṙ: spherical volume change',r's: species index'], r'notes':[r'Expansion lowers pressure at fixed mass and temperature',r'Evaporation or heating can oppose the geometric pressure decrease']},
    r'A radius-only gas law hides mass and thermal changes.', r'仅由半径决定的气体定律会隐藏质量与热变化。'))
b.append(P(
    "<strong>Step 24 — Limit saturation by inventory.</strong> Prescribe temperature and free vapor volume in a closed nondissolving control. Saturated mass equals pressure × volume/(gas constant × temperature). If it exceeds supply, all PFC vaporizes and partial pressure falls below saturation. Assume rapid equilibrium, negligible curvature corrections and coexistence conditions. This algebra supplies an equilibrium control, not a rate law.",
    "<strong>步骤 24——用物质量限制饱和。</strong> 在封闭、无溶解对照中给定温度及自由蒸气体积。饱和质量等于压力 × 体积／（气体常数 × 温度）。所需质量超过供给时，PFC 全部汽化，分压低于饱和。假设快速平衡、曲率修正可忽略并满足共存条件。该代数关系是平衡对照，并非速率规律。"))
b.append(E(r'C2-E26', r'm_{v,\mathrm{eq}}=\min\!\left[m_{\mathrm{PFC},0},\frac{M_{\mathrm{PFC}}p_{\mathrm{sat,PFC}}(T_b)V_b}{R_uT_b}\right],\qquad p_{v,\mathrm{PFC,eq}}=\min\!\left[p_{\mathrm{sat,PFC}}(T_b),\frac{m_{\mathrm{PFC},0}R_uT_b}{M_{\mathrm{PFC}}V_b}\right]',
    r'$m_{v,\mathrm{eq}}$ is equilibrium PFC vapor mass (kg), eq labeling the restricted equilibrium control; $m_{\mathrm{PFC},0}$ is finite initial supply (kg); $M_{\mathrm{PFC}}$ is PFC molar mass (kg mol⁻¹); $p_{\mathrm{sat,PFC}}(T_b)$ is bulk saturation pressure (Pa); $p_{v,\mathrm{PFC,eq}}$ is ideal equilibrium PFC partial pressure (Pa); $T_b>0$ is prescribed temperature (K); $V_b>0$ is available vapor volume (m³); $R_u$ is universal gas constant (J mol⁻¹ K⁻¹); $\min$ selects the lesser nonnegative argument. The supply is closed and nondissolving, and mass exchange is assumed fast.',
    r'$m_{v,\mathrm{eq}}$ 为平衡 PFC 蒸汽质量（kg），eq 标记受限平衡参照；$m_{\mathrm{PFC},0}$ 为有限初始供应（kg）；$M_{\mathrm{PFC}}$ 为 PFC 摩尔质量（kg mol⁻¹）；$p_{\mathrm{sat,PFC}}(T_b)$ 为体相饱和蒸汽压（Pa）；$p_{v,\mathrm{PFC,eq}}$ 为理想平衡 PFC 分压（Pa）；$T_b>0$ 为给定温度（K）；$V_b>0$ 为可用蒸汽体积（m³）；$R_u$ 为通用气体常数（J mol⁻¹ K⁻¹）；$\min$ 选择较小非负值。供应闭合且不溶解，并假设质量交换迅速。',
    r'Finite-inventory equilibrium benchmark', {r'type':r'phase',r'labels':[r'm_PFC,0: total available compound',r'm_v,eq: actual equilibrium vapor mass',r'M_PFC, R_u: mole-to-mass conversion',r'T_b: prescribed thermal state',r'V_b: available vapor volume',r'p_sat,PFC: coexistence ceiling',r'p_v,PFC,eq: inventory-limited pressure',r'min: choose supply or saturation branch'], r'notes':[r'Small vapor volume can coexist with remaining liquid',r'A fully vaporized large volume cannot maintain saturation without more PFC']},
    r'The saturation branch ends when the finite liquid inventory is exhausted.', r'有限液体库存耗尽时，饱和分支终止。'))

b.append(H("2.5 Single-core numerical example", "2.5 单核心数值示例", r'benchmark'))
b.append(P(
    "Prescribe a 5 μm PFP-like liquid core at 293 K. Final vapor reference temperature is 323 K. Use density 1630 kg m⁻³, liquid heat capacity 654 J kg⁻¹ K⁻¹, and latent enthalpy 95 kJ kg⁻¹. Molar mass is the named PFP value. Size, density, constant coefficients and final state are teaching inputs. The latent value is not a 323 K NIST datum. Verified nanoformulation properties remain unestablished.",
    "规定 293 K、半径 5 μm 的类 PFP 液核。最终蒸气参照温度为 323 K。采用密度 1630 kg m⁻³、液体热容 654 J kg⁻¹ K⁻¹、潜焓 95 kJ kg⁻¹。摩尔质量采用具名 PFP 数值。尺寸、密度、常系数及最终状态为教学输入。潜焓并非 323 K 的 NIST 数据。已验证纳米配方物性尚未确立。"))
b.append(P(
    "<strong>Step 25 — Calculate initial mass.</strong> Cube radius in meters. Multiply by density and the sphere-volume factor. One nanogram equals $10^{-12}$ kg.",
    "<strong>步骤 25——计算初始质量。</strong> 将以米计的半径取三次方，乘以密度和球体积系数。一纳克等于 $10^{-12}$ kg。"))
b.append(E(r'C2-E27', r'm_{\mathrm{PFC},0}=\frac{4\pi}{3}(1630)(5\times10^{-6})^3=8.534660\times10^{-13}\ \mathrm{kg}=0.853466\ \mathrm{ng}',
    r'$m_{\mathrm{PFC},0}$ is initial PFC mass (kg), 0 labeling initial state; 1630 is density in kg m⁻³; $5\times10^{-6}$ is initial radius in m; $\pi$ is the circular constant; the cube is a power; ng denotes nanogram, $1$ ng = $10^{-12}$ kg.',
    r'$m_{\mathrm{PFC},0}$ 为初始 PFC 质量（kg），0 表示初态；1630 为以 kg m⁻³ 计的密度；$5\times10^{-6}$ 为以 m 计的初始半径；$\pi$ 为圆周率；立方表示幂；ng 为纳克，$1$ ng = $10^{-12}$ kg。',
    r'Finite-mass worked calculation', {r'type':r'sphere',r'labels':[r'a₀ = 5 μm',r'ρ_d = 1630 kg/m³',r'm_PFC,0 = 0.853466 ng',r'π: spherical volume'], r'notes':[r'This is a micron-scale teaching core',r'All later PFC phases share this mass inventory']},
    r'A mass ledger begins with the actual core volume.', r'质量账目从实际核心体积开始。'))
b.append(P(
    "<strong>Step 26 — Estimate preparation enthalpy.</strong> Prescribe heating followed by vaporization near constant pressure. Use constant heat capacity and latent enthalpy. Sensible energy equals mass × heat capacity × temperature rise. Latent energy equals mass × latent enthalpy. This screen omits pressure-path detail, carrier heat, shell work, gradients and losses. Activation threshold and jet energy remain unestablished.",
    "<strong>步骤 26——估算制备焓。</strong> 规定近恒压下先加热再汽化，采用恒定热容和潜焓。显热等于质量 × 热容 × 温升，潜热等于质量 × 潜焓。该筛选省略详细压力路径、载液加热、壳层功、梯度及损失。激活阈值与射流能量尚未确立。"))
b.append(E(r'C2-E28', r'\begin{aligned}Q_{\mathrm{sens}}&\approx m_{\mathrm{PFC},0}c_{p,d}(T_*-T_0)=(8.534660\times10^{-13})(654)(323-293)=16.7450\ \mathrm{nJ},\\Q_{\mathrm{lat}}&\approx m_{\mathrm{PFC},0}L_v=(8.534660\times10^{-13})(95000)=81.0793\ \mathrm{nJ},\\Q_{\mathrm{prep}}&\approx Q_{\mathrm{sens}}+Q_{\mathrm{lat}}=97.8243\ \mathrm{nJ}.\end{aligned}',
    r'$Q_{\mathrm{sens}},Q_{\mathrm{lat}},Q_{\mathrm{prep}}$ are estimated sensible, latent, and total preparation energies (J), named by their subscripts; $m_{\mathrm{PFC},0}$ is mass (kg); $c_{p,d}=654$ J kg⁻¹ K⁻¹ is constant liquid heat capacity; $T_*=323$ K is final reference temperature, star labeling the selected state rather than a critical nucleus; $T_0=293$ K is initial temperature; $L_v=95000$ J kg⁻¹ is declared latent enthalpy; nJ means $10^{-9}$ J; $\approx$ denotes the constant-property preparation estimate.',
    r'$Q_{\mathrm{sens}},Q_{\mathrm{lat}},Q_{\mathrm{prep}}$ 为显热、潜热及总制备能量估计（J），下标表示其含义；$m_{\mathrm{PFC},0}$ 为质量（kg）；$c_{p,d}=654$ J kg⁻¹ K⁻¹ 为常液相比热容；$T_*=323$ K 为最终参照温度，此处星号标记所选状态，不是临界汽核；$T_0=293$ K 为初始温度；$L_v=95000$ J kg⁻¹ 为声明的潜焓；nJ 表示 $10^{-9}$ J；$\approx$ 表示常性质制备估计。',
    r'Declared preparation-path enthalpy estimate', {r'type':r'energy',r'labels':[r'm_PFC,0: finite core mass',r'T₀ = 293 K → T_* = 323 K',r'c_p,d = 654 J/(kg K)',r'L_v = 95 kJ/kg',r'Q_sens = 16.7450 nJ',r'Q_lat = 81.0793 nJ',r'Q_prep = 97.8243 nJ'], r'notes':[r'Sensible plus latent preparation energy',r'Carrier losses and mechanical work require a broader energy ledger']},
    r'Most of this declared preparation estimate is latent enthalpy.', r'该制备估计中的大部分能量是潜焓。'))
b.append(P(
    "<strong>Refine the enthalpy path.</strong> At near-constant pressure, heat subcooled liquid to saturation. Vaporize it, then heat vapor to the final temperature. Integrate each phase heat capacity over its own interval. The 97.82 nJ screen instead applies liquid heat capacity over 30 K plus fixed latent enthalpy. Exact endpoint enthalpy requires vapor heat capacity and the actual pressure path.",
    "<strong>细化焓路径。</strong> 近恒压下先将过冷液体加热至饱和，再汽化，然后将蒸气加热至最终温度。分别在各温区积分对应相热容。97.82 nJ 筛选则在整个 30 K 温升使用液体热容，再加固定潜焓。精确终态焓需要蒸气热容及实际压力路径。"))
b.append(E(r'C2-E29', r'Q_{\mathrm{iso}}=m_{\mathrm{PFC},0}\!\left[\int_{T_0}^{T_{\mathrm{sat}}}c_{p,l}(T,p)\,dT+L_v(T_{\mathrm{sat}},p)+\int_{T_{\mathrm{sat}}}^{T_*}c_{p,v}(T,p)\,dT\right],\qquad T_0<T_{\mathrm{sat}}\le T_*',
    r'$Q_{\mathrm{iso}}$ is heat needed for the stated constant-pressure preparation path (J), iso labeling isobaric; $m_{\mathrm{PFC},0}$ is conserved PFC mass (kg); $p$ is prescribed constant pressure (Pa); $T_0,T_{\mathrm{sat}},T_*$ are initial liquid, coexistence, and final vapor temperatures (K), with sat naming saturation and star the selected final state; $T$ is dummy integration temperature (K); $c_{p,l},c_{p,v}$ are temperature- and pressure-dependent liquid/vapor constant-pressure specific heats (J kg⁻¹ K⁻¹); $L_v(T_{\mathrm{sat}},p)$ is latent enthalpy at coexistence (J kg⁻¹); $\int$ denotes temperature integration. No heat losses or other work are included; pressure work is already contained in this enthalpy path.',
    r'$Q_{\mathrm{iso}}$ 为所述恒压制备路径的需热（J），iso 表示等压；$m_{\mathrm{PFC},0}$ 为守恒 PFC 质量（kg）；$p$ 为给定常压力（Pa）；$T_0,T_{\mathrm{sat}},T_*$ 为初始液体、共存及最终蒸汽温度（K），sat 表示饱和，星号表示所选最终状态；$T$ 为积分哑温度（K）；$c_{p,l},c_{p,v}$ 为依赖温度与压力的液／汽定压比热（J kg⁻¹ K⁻¹）；$L_v(T_{\mathrm{sat}},p)$ 为共存状态潜焓（J kg⁻¹）；$\int$ 为温度积分。未计入热损失或其他做功；压力功已包含在该焓路径中。',
    r'Refined constant-pressure enthalpy path', {r'type':r'energy',r'labels':[r'm_PFC,0: fixed compound mass',r'p: constant path pressure',r'T₀ → T_sat: liquid heating',r'T_sat: phase transition',r'T_sat → T_*: vapor heating',r'c_p,l, c_p,v: phase heat capacities',r'L_v(T_sat,p): coexistence latent enthalpy',r'Q_iso: total path heat',r'T, dT: temperature integration'],r'notes':[r'Latent enthalpy already contains the phase-transition flow work',r'The constant-property screen does not replace a calibrated enthalpy path']},
    r'A rigorous preparation path uses the heat capacity of each phase over its own interval.', r'严谨制备路径在各相自身温区使用对应比热容。'))
b.append(P(
    "<strong>Step 27 — Calculate an inventory radius.</strong> Fully vaporize the supply at 323 K and 100 kPa PFC partial pressure. Use the ideal-vapor control. Equate gas-law volume to initial volume × expansion factor. Cancel the positive sphere factor and take the positive cube root. The resulting radius belongs to the prescribed state. Dynamical maximum remains unestablished.",
    "<strong>步骤 27——计算物质量对应半径。</strong> 在 323 K、PFC 分压 100 kPa 下完全汽化该供给，采用理想蒸气对照。令气体定律体积等于初始体积乘膨胀倍数。约去正球体系数并取正立方根。所得半径属于指定状态。动力学最大值尚未确立。"))
b.append(E(r'C2-E30', r'\begin{aligned}\frac{4\pi}{3}R_{b,\mathrm{inv}}^3&=\frac{m_{\mathrm{PFC},0}R_uT_*}{M_{\mathrm{PFC}}p_{v,\mathrm{PFC}}}=\frac{4\pi}{3}\rho_da_0^3\frac{R_uT_*}{M_{\mathrm{PFC}}p_{v,\mathrm{PFC}}},\\\left(\frac{R_{b,\mathrm{inv}}}{a_0}\right)^3&=\frac{\rho_dR_uT_*}{M_{\mathrm{PFC}}p_{v,\mathrm{PFC}}}=151.9778,\\R_{b,\mathrm{inv}}&=a_0(151.9778)^{1/3}=26.6827\ \mu\mathrm m.\end{aligned}',
    r'$R_{b,\mathrm{inv}}>0$ is ideal inventory-state bubble radius (m), b naming bubble and inv naming inventory; $a_0=5$ μm is initial core radius; $m_{\mathrm{PFC},0}$ is initial mass (kg); $\rho_d=1630$ kg m⁻³ is original liquid density; $R_u=8.314462618$ J mol⁻¹ K⁻¹ is gas constant; $T_*=323$ K is chosen final reference; $M_{\mathrm{PFC}}=0.2880343$ kg mol⁻¹ is PFP molar mass; $p_{v,\mathrm{PFC}}=10^5$ Pa is chosen partial pressure; $\pi$ is the circular constant; powers 3 and 1/3 denote cube and positive cube root. The ratio is dimensionless.',
    r'$R_{b,\mathrm{inv}}>0$ 为理想库存状态气泡半径（m），b 表示气泡，inv 表示库存；$a_0=5$ μm 为初始核心半径；$m_{\mathrm{PFC},0}$ 为初始质量（kg）；$\rho_d=1630$ kg m⁻³ 为初始液体密度；$R_u=8.314462618$ J mol⁻¹ K⁻¹ 为气体常数；$T_*=323$ K 为选定最终参照；$M_{\mathrm{PFC}}=0.2880343$ kg mol⁻¹ 为 PFP 摩尔质量；$p_{v,\mathrm{PFC}}=10^5$ Pa 为所选分压；$\pi$ 为圆周率；幂 3 和 1/3 表示立方及正立方根。该比值无量纲。',
    r'Derived ideal-vapor inventory radius', {r'type':r'sphere',r'labels':[r'a₀ = 5 μm: original liquid',r'R_b,inv = 26.6827 μm: assumed vapor state',r'm_PFC,0, ρ_d: original inventory',r'T_* = 323 K',r'p_v,PFC = 100 kPa',r'M_PFC, R_u: ideal mole relation',r'151.9778: volume expansion',r'π: sphere geometry'], r'notes':[r'Volume ratio is about 152; radius ratio about 5.34',r'Inventory radius is not dynamical R_max']},
    r'The expansion ratio follows from mass conservation at a stated pressure and temperature.', r'膨胀比来自指定压力与温度下的质量守恒。'))
