    r'Original activation-probability formula', {r'type':r'nucleation',r'labels':[r'T, p: local hot state',r'J: supplied event rate',r'V_d(t′): available liquid',r't, t′, dV: event integration',r'P_act: activation probability'], r'notes':[r'A rate law or calibrated activation law is still required',r'One absent event does not prove impossibility']},
